parameters.jsCode:
const src = {
  status: {
    title: $json.status_title || 'AI Output Corruption Blocked',
    category: $json.status_category || $json.titan_category || 'json_parse_error',
    severity: $json.status_severity || 'error',
  },
  decision: {
    route: $json.decision_route || 'payload_sanitization',
    action: $json.decision_action || 'sanitize_ai_output_before_execution',
    manual_review_required: false,
  },
  execution: {
    allowed: false,
  },
  titan_audit: {
    confidence_score: $json.confidence || 'Deterministic contamination signal',
    safe_to_execute: false,
    manual_review_required: false,
    next_step_recommendation: $json.next_step || 'Repair and validate payload before retry',
    decision: {
      route: $json.decision_route || 'payload_sanitization',
    },
  },
  telemetry: {
    input_type: 'ai_output_contamination',
    detection_source: 'n8n_template_guard',
    error_signature: $json.titan_category || 'json_parse_error',
    signature: {
      provider: 'n8n',
      error_type: 'ai_output_contamination',
      line: 6,
      column: 31,
      snippet: $json.summary || $json.reason || '',
    },
  },
  resolver: {
    safe_to_autofix: false,
  },
  response:
    `Meaning:\n${$json.summary || $json.reason || 'Titan blocked malformed AI-generated content before downstream workflow execution.'}\n\nNext step:\n${$json.next_step || 'Sanitize AI output, escape quotes or unsafe line breaks, validate the request body, then retry.'}`,
};

function get(obj, path, fallback = '') {
	try {
		const value = path.split('.').reduce((o, key) => (o || {})[key], obj);
		return value ?? fallback;
	} catch {
		return fallback;
	}
}

function pick(...values) {
	for (const value of values) {
		if (value !== undefined && value !== null && value !== '') return value;
	}
	return '';
}

function toText(value) {
	if (value === null || value === undefined || value === '') return '';
	if (typeof value === 'string') return value;
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

function truncate(value, max = 1200) {
	const output = toText(value);
	if (output.length <= max) return output;
	return `${output.slice(0, max)}\n…truncated`;
}

function isNonEmptyArray(value) {
	return Array.isArray(value) && value.length > 0;
}

function codeBlock(label, value, max = 900) {
	if (!value || toText(value) === '[]' || toText(value) === '{}') return null;
	return {
		type: 'section',
		text: {
			type: 'mrkdwn',
			text: `\n*${label}*\n\`\`\`\n${truncate(value, max)}\n\`\`\``,
		},
	};
}

function addBlock(blocks, block) {
	if (block) blocks.push(block);
}

function cleanValue(value, fallback = '-') {
	const text = toText(value).trim();
	if (!text || text === 'None' || text === 'null' || text === 'undefined') return fallback;
	return text.replace(':None', '');
}

function extractResponseSections(responseText) {
	const text = toText(responseText);

	const sections = {
		message: '',
		meaning: '',
		likelyCause: '',
		nextStep: '',
	};

	const meaningMatch = text.match(/Meaning:\n([\s\S]*?)(\n\nLikely cause:|\n\nNext step:|\n\nInput type:|$)/i);
	const likelyMatch = text.match(/Likely cause:\s*([\s\S]*?)(\n\nTitan has|\n\nNext step:|\n\nInput type:|$)/i);
	const nextMatch = text.match(/Next step:\n([\s\S]*?)(\n\nInput type:|$)/i);

	sections.meaning = meaningMatch ? meaningMatch[1].trim() : '';
	sections.likelyCause = likelyMatch ? likelyMatch[1].trim() : '';
	sections.nextStep = nextMatch ? nextMatch[1].trim() : '';

	const firstLines = text.split('\n').filter(Boolean);
	sections.message = firstLines.slice(0, 2).join(' — ');

	return sections;
}

const title = pick(get(src, 'status.title'), 'Titan Signal');
const category = pick(get(src, 'status.category'), 'unknown');
const severity = pick(get(src, 'status.severity'), 'info');

const responseText = typeof src.response === 'string' ? src.response : '';
const sections = extractResponseSections(responseText);

const route = pick(get(src, 'decision.route'), get(src, 'titan_audit.decision.route'), 'unknown');
const action = pick(get(src, 'decision.action'), get(src, 'titan_audit.next_step_recommendation'), 'review_required');

const manualReview = get(src, 'decision.manual_review_required') === true || get(src, 'titan_audit.manual_review_required') === true;
const safeToExecute = get(src, 'titan_audit.safe_to_execute');
const safeToAutofix = get(src, 'resolver.safe_to_autofix');

const provider = pick(get(src, 'telemetry.signature.provider'), 'unknown');
const errorType = pick(get(src, 'telemetry.signature.error_type'), 'unknown');
const line = pick(get(src, 'telemetry.signature.line'), '-');
const column = pick(get(src, 'telemetry.signature.column'), '-');
const snippet = pick(get(src, 'telemetry.signature.snippet'), get(src, 'telemetry.user_text'));

const inputType = pick(get(src, 'telemetry.input_type'), 'unknown');
const detectionSource = pick(get(src, 'telemetry.detection_source'), 'unknown');
const signature = pick(get(src, 'telemetry.error_signature'), category);
const confidenceRaw = pick(
	get(src, 'titan_audit.confidence_score'),
	get(src, 'execution.confidence'),
	get(src, 'resolver.confidence'),
	'unknown'
);

const confidence = String(detectionSource || '').includes('cascade_override')
	? 'Deterministic (100%)'
	: confidenceRaw;

const transformations = get(src, 'titan_audit.transformations', []);
const correctedFields = get(src, 'resolver.corrected_fields', []);
const missingFields = get(src, 'resolver.missing_fields', []);
const extraFields = get(src, 'resolver.extra_fields', []);
const uncorrectableFields = get(src, 'resolver.uncorrectable_fields', []);
const resolverCandidate = get(src, 'resolver.candidate');

const topLevelCascadeDetected = get(src, 'cascade.cascade_detected') === true;
const detailsCascadeDetected = get(src, 'response.details.cascade_detected') === true;
const detectionIndicatesCascade = String(detectionSource || '').includes('cascade_override');

const cascadeDetected = Boolean(
	topLevelCascadeDetected ||
	detailsCascadeDetected ||
	detectionIndicatesCascade
);

const primaryIssue = cascadeDetected
	? pick(
		get(src, 'cascade.primary_failure'),
		get(src, 'response.details.primary_failure'),
		category
	)
	: null;

const secondarySignal = cascadeDetected
	? pick(
		get(src, 'cascade.secondary_failure'),
		get(src, 'response.details.secondary_failure'),
		String(snippet || '').includes('TypeError') ? 'runtime_error' : 'none'
	)
	: 'none';

const fixOrder = cascadeDetected
	? pick(
		get(src, 'cascade.fix_priority_order'),
		get(src, 'response.details.fix_priority_order'),
		[
			'Repair malformed JSON.',
			'Retry the workflow.',
			'Investigate the runtime error only if it persists.'
		]
	)
	: [];

let color = '#2E7D32';
let header = '🟢 TITAN SIGNAL';

if (severity === 'error') {
	color = '#D32F2F';
	header = '🔴 TITAN SIGNAL';
} else if (severity === 'warning') {
	color = '#F9A825';
	header = '🟠 TITAN SIGNAL';
}

if (manualReview) {
	color = '#D32F2F';
	header = '🚨 TITAN MANUAL REVIEW';
}

const decisionEmoji = manualReview ? '🚨' : safeToAutofix ? '🛠️' : severity === 'error' ? '🔴' : severity === 'warning' ? '🟠' : '🟢';

if (inputType === 'ai_output_contamination') {
	actionText =
		'Sanitize AI output, escape quotes or unsafe line breaks, validate the request body, then retry.';
} else if (category === 'json_parse_error') {
	actionText =
		'Fix this first: repair the malformed JSON, then retry the workflow.';
}
if (category === 'dependency_error') {
	actionText = 'Fix this first: install or resolve the missing dependency, then rebuild and retry.';
} else if (category === 'missing_fields') {
	actionText = 'Fix this first: add the missing required fields, then retry the request.';
} else if (category === 'schema_corrected') {
	actionText = 'Review the corrected fields and update your payload to match the expected schema.';
} else if (category === 'schema_partially_corrected_blocked') {
	actionText = 'Fix the remaining blocking fields before retrying the request.';
} else if (category === 'auth_error') {
	actionText = 'Fix this first: correct the API key or authentication configuration, then retry.';
} else if (category === 'infrastructure_error') {
	actionText = 'Check provider status, network connectivity, DNS, timeout settings, and retry after a short delay.';
} else if (category === 'runtime_error') {
	actionText = 'Inspect the failing step and fix undefined/null values before retrying.';
} else {
	actionText = sections.nextStep
		? sections.nextStep
		: action !== 'unknown'
			? `Follow route: \`${action}\`.`
			: 'Review the Titan response before continuing.';
}

const shareableSummary = cascadeDetected
	? `${decisionEmoji} Titan found the root cause: ${primaryIssue || category}. Fix this first before addressing ${secondarySignal || 'secondary errors'}.`
	: `${decisionEmoji} Titan detected ${title}. Action: ${action}. Safe to execute: ${safeToExecute}.`;

const blocks = [];

blocks.push({
	type: 'header',
	text: {
		type: 'plain_text',
		text: header,
	},
});

blocks.push({
	type: 'section',
	text: {
		type: 'mrkdwn',
		text:
			`*${title}*\n` +
			`*Severity:* \`${severity}\`    *Category:* \`${category}\`\n` +
			`*Decision:* \`${route}\` → \`${action}\`\n` +
			`*Confidence:* \`${confidence}\`    *Manual review:* \`${manualReview}\``,
	},
});

if (cascadeDetected) {
	const fixOrderText = Array.isArray(fixOrder) && fixOrder.length
		? fixOrder.map((step, index) => `${index + 1}. ${step}`).join('\n')
		: '1. Resolve the primary issue first.\n2. Retry the workflow.\n3. Review any remaining secondary signal.';

	blocks.push({
		type: 'section',
		text: {
			type: 'mrkdwn',
			text:
				`\n*⚠️ Cascade Detected*\n` +
				`Primary issue: \`${primaryIssue || category}\`\n` +
				`Secondary signal: \`${secondarySignal || 'none'}\`\n\n` +
				`*Fix order*\n${fixOrderText}`,
		},
	});
}

blocks.push({
	type: 'section',
	text: {
		type: 'mrkdwn',
		text: `\n*What to do next*\n${truncate(actionText, 700)}`,
	},
});

let whyText = sections.meaning;

if (cascadeDetected && category === 'json_parse_error') {
	whyText = 'Titan detected a malformed JSON fragment embedded in the input. Because JSON parsing fails before execution begins, it becomes the primary blocking failure and prevents downstream steps from running correctly.';
}

if (whyText) {
	blocks.push({
		type: 'section',
		text: {
			type: 'mrkdwn',
			text: `\n*Why Titan flagged this*\n${truncate(whyText, 900)}`,
		},
	});
}

if (sections.likelyCause) {
	blocks.push({
		type: 'section',
		text: {
			type: 'mrkdwn',
			text: `\n*Likely cause*\n${truncate(sections.likelyCause, 900)}`,
		},
	});
}

if (isNonEmptyArray(transformations)) {
	addBlock(blocks, codeBlock('Titan Correction Receipt', transformations, 1000));
}

if (resolverCandidate) {
	addBlock(blocks, codeBlock('Corrected Payload Candidate', resolverCandidate, 1000));
}

if (isNonEmptyArray(correctedFields)) {
	addBlock(blocks, codeBlock('Corrected Fields', correctedFields, 700));
}

if (isNonEmptyArray(missingFields)) {
	addBlock(blocks, codeBlock('Missing Fields', missingFields, 700));
}

if (isNonEmptyArray(extraFields)) {
	addBlock(blocks, codeBlock('Extra Fields', extraFields, 700));
}

if (isNonEmptyArray(uncorrectableFields)) {
	addBlock(blocks, codeBlock('Uncorrectable Fields', uncorrectableFields, 700));
}

blocks.push({
	type: 'section',
	text: {
		type: 'mrkdwn',
		text:
			`\n*Execution Guard*\n` +
			`Safe to execute: \`${safeToExecute}\`\n` +
			`Safe autofix: \`${safeToAutofix}\`\n` +
			`Input type: \`${inputType}\`\n` +
			`Detection: \`${detectionSource}\``,
	},
});

blocks.push({ type: 'divider' });

const cleanSignature = cleanValue(signature, category);
const cleanLine = cleanValue(line, '-');
const cleanColumn = cleanValue(column, '-');

blocks.push({
	type: 'section',
	text: {
		type: 'mrkdwn',
		text:
			`\n*Metadata*\n` +
			`Provider: \`${provider}\`\n` +
			`Error: \`${errorType}\`\n` +
			`Signature: \`${cleanSignature}\`\n` +
			`Location: line \`${cleanLine}\`, column \`${cleanColumn}\``,
	},
});

if (snippet) {
	blocks.push({
		type: 'section',
		text: {
			type: 'mrkdwn',
			text: `\n*Relevant Snippet*\n\`\`\`\n${truncate(snippet, 900)}\n\`\`\``,
		},
	});
}

blocks.push({
	type: 'section',
	text: {
		type: 'mrkdwn',
		text: `\n*Shareable Summary*\n${shareableSummary}`,
	},
});

return [
	{
		json: {
			slack_text: `${header} - ${title}`,
			slack_color: color,
			slack_blocks: blocks,
			slack_attachments: [
				{
					color,
					fallback: shareableSummary,
					blocks,
				},
			],
			shareable_summary: shareableSummary,
		},
	},
];
